    'Countries (two-letter codes, e.g. ES, FR, DE)' => 'Nchi (misimbo ya herufi mbili, mf. ES, FR, DE)',
    'Country list: not downloaded yet (it is downloaded when you switch the filter on).' => 'Orodha ya nchi: bado haijapakuliwa (inapakuliwa unapowasha kichujio).',
    'Country list of %s.' => 'Orodha ya nchi ya %s.',
    'Update the country list' => 'Sasisha orodha ya nchi',
